properties.query:
let windowSize = 2h;
let AoiBounds = _GetWatchlist('AOI_Boundary_List') | project MissionId;
// S12: 임무 자기승인
let S12 =
    UAVMissionPlan_CL
    | where TimeGenerated > ago(windowSize)
    | where Planner == Approver
    | project T1=TimeGenerated, MissionId=tostring(MissionId), OperatorId=Planner;
// S16: AOI 이탈
let S16 =
    UAVTelemetry_CL
    | where TimeGenerated > ago(windowSize)
    | where MsgType == 'GLOBAL_POSITION_INT'
    | join kind=leftanti (AoiBounds) on $left.MissionId == $right.MissionId
    | summarize ExcursionCount=count(), T2=min(TimeGenerated)
        by MissionId=tostring(MissionId)
    | where ExcursionCount >= 3;
// S3: SATCOM 무결성 이상
let S3 =
    UAVSatcomLink_CL
    | where TimeGenerated > ago(windowSize)
    | where IntegrityStatus != 'ok' or toreal(JamIndicator) > 0.15
    | summarize T3=min(TimeGenerated) by SessionId;
S12
| join kind=inner (S16) on MissionId
| where T2 >= T1 and T2 <= T1 + 60m
| join kind=inner (S3)
    on $left.T2 <= $right.T3 and $right.T3 <= ($left.T2 + 60m)
| extend CampaignType = "C3_자기승인임무_AOI이탈_SATCOM유출"
| extend StepSummary = strcat("S12@", tostring(T1), " → S16@", tostring(T2), " → S3@", tostring(T3))
| extend Severity = "High"
| project T1, T2, T3, MissionId, OperatorId, CampaignType, StepSummary, Severity
